-- Alfazy seed: game row (per school) + word dictionary. Idempotent.

-- 1. Register the Alfazy game for every school that doesn't have it yet.
SELECT gen_random_uuid(), s."id", 'alfazy', 'Alfazy', 'word', 'single', '{}'::jsonb, true, CURRENT_TIMESTAMP
FROM "schools" s
WHERE NOT EXISTS (SELECT 1 FROM "games" g WHERE g."school_id" = s."id" AND g."key" = 'alfazy');

